/* Hero background: stylised shipping-route field (pure SVG/CSS, no images). */
function heroBg(){
  /* one origin hub on the left, routes fanning out across the field */
  const arcs=[
    "M150 316 C300 214, 560 168, 830 150 S1230 128, 1428 104",
    "M150 316 C320 268, 600 250, 880 258 S1250 276, 1432 268",
    "M150 316 C310 336, 610 366, 900 384 S1258 412, 1436 420",
    "M150 316 C286 404, 566 470, 862 500 S1236 552, 1430 574",
    "M150 316 C340 176, 660 92, 980 62 S1300 34, 1438 26"
  ];
  const ports=[[150,316],
               [1428,104],[1432,268],[1436,420],[1430,574],[1438,26],
               [830,150],[880,258],[900,384],[862,500],[980,62]];
  return `<div class="hero-bg" aria-hidden="true">
    <svg viewBox="0 0 1440 620" preserveAspectRatio="xMidYMid slice" focusable="false">
      ${arcs.map(d=>`<path class="arc" d="${d}"/>`).join("")}
      <path class="flow" d="${arcs[1]}"/>
      <path class="flow f2" d="${arcs[3]}"/>
      <path class="flow f3" d="${arcs[0]}"/>
      ${ports.map(([x,y],i)=>`<circle class="port${i===0?" hub":""}" cx="${x}" cy="${y}" r="${i===0?5:2.4}"/>`).join("")}
      <circle class="halo" cx="150" cy="316" r="5"/>
      <circle class="halo h2" cx="150" cy="316" r="5"/>
      <circle class="halo h3" cx="150" cy="316" r="5"/>
    </svg>
  </div>`;
}

