function pageQualify(){
  const p = new URLSearchParams(location.search||"");
  const ctx = p.get("deal")||p.get("pkg")||p.get("type")||"";
  const S = Q_STEPS();
  const fld = f => {
    const id="qf_"+f.k, req=f.req?' aria-required="true"':"", dsc=` aria-describedby="${id}_e"`;
    if(f.ty==="radio"||f.ty==="check") return `<div class="opts" role="group" aria-labelledby="${id}_l"${dsc}>${f.o.map((o,i)=>
      `<label class="opt"><input type="${f.ty==="radio"?"radio":"checkbox"}" name="${f.k}" value="${esc(o)}"><span>${o}</span></label>`).join("")}</div>`;
    if(f.ty==="select") return `<select id="${id}" name="${f.k}"${req}${dsc}><option value="">${L("اختر…","Select…")}</option>${f.o.map(o=>`<option>${o}</option>`).join("")}</select>`;
    if(f.ty==="textarea") return `<textarea id="${id}" name="${f.k}"${req}${dsc} placeholder="${esc(f.h||"")}"></textarea>`;
    const pat = f.ty==="tel" ? ' pattern="[+]?[0-9\\s()\\-]{7,}" inputmode="tel"' : "";
    return `<input id="${id}" type="${f.ty}" name="${f.k}"${req}${dsc}${pat}>`;
  };
  return `<section class="sec tight sand"><div class="wrap">
    <span class="eyebrow">${L("نموذج التأهيل","Qualification form")}</span>
    <h1 style="font-size:clamp(1.6rem,4vw,2.4rem)">${L("أخبرنا عن وضعك الحالي","Tell us where you are today")}</h1>
    <p class="lead">${L("الهدف من هذا النموذج ليس البيع، بل معرفة ما إذا كانت الصفقة مناسبة لك أصلًا. إجابات دقيقة تعني توصية دقيقة — أو نصيحة بالانتظار إن لم يكن التوقيت مناسبًا.","The purpose of this form is not to sell, but to work out whether a deal genuinely suits you. Accurate answers mean an accurate recommendation — or advice to wait if the timing is wrong.")}</p>
  </div></section>
  <section class="sec"><div class="wrap" style="max-width:760px">
    <div class="form" id="qf">
      <div class="progress"><i id="bar"></i></div>
      <div class="stepnum"><span id="stitle"></span><span id="scount"></span></div>
      <form id="qform" novalidate>
        <input type="hidden" name="context" value="${esc(ctx)}">
        ${S.map((s,si)=>`<div class="fstep${si===0?" on":""}" data-s="${si}">
          ${s.f.map(f=>`<div class="field"><label id="qf_${f.k}_l"${(f.ty==="radio"||f.ty==="check")?"":` for="qf_${f.k}"`}>${f.l}${f.req?"":` <span class="hint">(${L("اختياري","optional")})</span>`}</label>${fld(f)}<div class="err" id="qf_${f.k}_e" data-for="${f.k}" role="alert">${L("هذا الحقل مطلوب","This field is required")}</div></div>`).join("")}
        </div>`).join("")}
        <div class="formnav">
          <button type="button" class="btn btn-out" id="prev" style="display:none">${L("السابق","Back")}</button>
          <button type="button" class="btn btn-primary" id="next">${L("التالي","Next")}</button>
          <button type="submit" class="btn btn-primary" id="send" style="display:none">${L("إرسال الطلب","Submit request")}</button>
        </div>
        <div id="q_err" class="notice" role="alert" tabindex="-1" hidden style="margin-top:14px"></div>
      </form>
    </div>
    <p class="muted center" style="font-size:.84rem;margin-top:14px">${L("بياناتك تُستخدم للرد على طلبك فقط ولا تُشارك مع أطراف ثالثة لأغراض تسويقية.","Your details are used only to respond to your request and are not shared with third parties for marketing.")}</p>
  </div></section>`;
}


